-- Independent, durable delivery state for each message generated by a new PIX payment.
-- No historical payments are enqueued by this migration.
BEGIN;
SET LOCAL lock_timeout = '5s';
CREATE TABLE IF NOT EXISTS money2_pix_whatsapp_outbox (
    pix_id bigint NOT NULL REFERENCES pix_cobrancas(id) ON DELETE CASCADE,
    tipo varchar(32) NOT NULL CHECK (tipo IN ('PIX_RECEBIDO','EMPRESTIMO_ATUALIZADO')),
    status varchar(16) NOT NULL DEFAULT 'PENDENTE'
        CHECK (status IN ('PENDENTE','PROCESSANDO','ACEITO','FALHOU')),
    tentativas integer NOT NULL DEFAULT 0,
    proxima_tentativa timestamp NOT NULL DEFAULT LOCALTIMESTAMP,
    bloqueado_em timestamp,
    lease_token varchar(36),
    dispositivo_id bigint,
    remote_device_id text,
    telefone text,
    cliente_nome text,
    mensagem text,
    dispatch_id text,
    erro text,
    dtcad timestamp NOT NULL DEFAULT LOCALTIMESTAMP,
    dtalter timestamp NOT NULL DEFAULT LOCALTIMESTAMP,
    PRIMARY KEY (pix_id,tipo)
);
CREATE INDEX IF NOT EXISTS idx_money2_pix_whatsapp_outbox_pending
    ON money2_pix_whatsapp_outbox(proxima_tentativa,pix_id)
    WHERE status IN ('PENDENTE','PROCESSANDO');
GRANT SELECT, INSERT, UPDATE ON money2_pix_whatsapp_outbox TO money2_app;
COMMIT;
